import{_ as i,o as t,c as e,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph Octopus Roadmap Planning series: RADOS GateWay (RGW)","description":"","frontmatter":{"title":"Ceph Octopus Roadmap Planning series: RADOS GateWay (RGW)","date":"2019-06-13T00:00:00.000Z","updated":"2019-06-14T00:00:00.000Z","tags":["Ceph","Distributed Storage","RADOS Gateway","Octopus Release","RGW"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Ceph_Octopus_Roadmap_Planning_series_-_RADOS_GateWay_RGW.md","filePath":"posts/2019/Ceph_Octopus_Roadmap_Planning_series_-_RADOS_GateWay_RGW.md","lastUpdated":1780459816000}'),o={name:"posts/2019/Ceph_Octopus_Roadmap_Planning_series_-_RADOS_GateWay_RGW.md"};function a(p,l,n,r,u,_){return t(),e("div",null,[...l[0]||(l[0]=[s('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： [请填写会议时间]</p><p><strong>参会人员</strong>： [请填写参会人员名单]</p><p><strong>会议主题</strong>： Ceph分布式存储系统开发讨论，重点讨论Octopus版本的功能规划和RADOS Gateway (RGW)。</p><p><strong>会议内容</strong>：</p><p><strong>一、议题讨论</strong></p><ol><li><p><strong>Nautilus版本功能更新</strong>：</p><ul><li>讨论了Nautilus版本的功能更新，包括OPA、Ozzy和AC等特性。</li><li>确认了Nautilus版本中的一些功能合并情况，例如Nautilus和Noah的PLC合并。</li><li>讨论了Nautilus版本中的同步请求合并，尚未宣布胜利。</li><li>认为远程组功能可能不会在Octopus版本中实现。</li></ul></li><li><p><strong>Octopus版本功能规划</strong>：</p><ul><li>讨论了Octopus版本的功能规划，包括S3 Select、复制、动态RBD等。</li><li>认为S3 Select和复制功能将在Octopus版本中实现。</li><li>讨论了动态RBD的解决方案，认为它需要先完成一些项目。</li><li>认为多站点部署的兼容性问题需要考虑向后兼容性。</li></ul></li><li><p><strong>元数据变更</strong>：</p><ul><li>讨论了元数据变更的步骤，包括将区域复制策略从区域组中分离出来。</li><li>认为元数据变更可能会影响bucket的复制策略和后端存储。</li><li>讨论了后端存储的插件化，认为需要先实现一个最小可行产品（MVP）。</li></ul></li><li><p><strong>测试</strong>：</p><ul><li>讨论了测试计划，包括混合集群测试、升级测试、scrub测试等。</li><li>认为需要测试混合集群的兼容性，并支持至少三个版本的向后兼容。</li><li>认为scrub测试的重要性，需要确保数据的一致性和完整性。</li></ul></li></ol><p><strong>二、决策事项</strong></p><ol><li>将Nautilus版本中的功能更新合并到Trello任务板中。</li><li>将Octopus版本的功能规划细化，并确定优先级。</li><li>制定元数据变更的详细步骤，并确定MVP。</li><li>制定测试计划，并确保测试覆盖所有关键场景。</li></ol><p><strong>三、后续行动计划</strong></p><ol><li>各参会人员根据会议讨论内容，完善Trello任务板，并分配任务。</li><li>定期召开会议，跟踪项目进度，并解决遇到的问题。</li><li>加强团队沟通，确保项目顺利进行。</li></ol><p><strong>四、备注</strong></p><ol><li>会议中涉及的部分计算机科学/ceph相关领域英文原文关键词： <ul><li>Nautilus</li><li>Octopus</li><li>S3 Select</li><li>Replication</li><li>Dynamic RBD</li><li>Metadata</li><li>MVP</li><li>Testing</li><li>OPA</li><li>Ozzy</li><li>AC</li><li>PLC</li><li>STS</li><li>Keystone</li><li>RGW</li><li>Hadoop</li><li>Scrub</li></ul></li><li>会议中提到的部分项目： <ul><li>OPA</li><li>Ozzy</li><li>AC</li><li>PLC</li><li>STS</li><li>Keystone</li><li>RGW</li><li>Hadoop</li><li>Scrub</li></ul></li><li>会议中提到的部分人员： <ul><li>Rebecca</li><li>Robin</li><li>Eric</li></ul></li></ol>',13)])])}const R=i(o,[["render",a]]);export{g as __pageData,R as default};
